-- Generated by npm run generate:court-seed from sql/lookup-court-and-crosswalk.sql.
-- 308 courts, 94 crosswalk rules.
-- DO NOT EDIT BY HAND: correct the source file and regenerate, or the
-- reviewed data and the migration diverge.
--
-- The source file lists 309 courts. 1 of them is also a MERGE
-- SOURCE — a spelling of another court, not a court — so it is dropped and the
-- list is 308. 1 SPLIT court part was resolved through the merge
-- map for the same reason. See the generator header.

-- ---- 309 courts ----

-- ---- 94 crosswalk rules ----

-- ==========================================================================
--  THE SEVEN "WRONG" VALUES — the firm's ruling, 24 August 2026
--
--  Source: sql/court-wrong-destinations.sql.
--
--  Five are real places where something happened; they are simply not courts,
--  and matter_destination already holds exactly this kind of value. Four are
--  added to that list, taking it 27 -> 31. Two are discarded: `/` and `26`
--  are not values. A discard is not a deletion — the row still loads, it
--  simply has no court, and legacy_court_raw keeps the original text (D10).
-- ==========================================================================


-- ==========================================================================
--  POSTCONDITIONS
--
--  308 courts and 94 crosswalk rules, from all 401 distinct court names in
--  الدعاوى.matterCourt, الجلسات.المحكمة and admin work table.المحكمة, reviewed
--  by the firm: 307 KEEP, 52 MERGE, 35 SPLIT, 7 WRONG.
--
--  **308, NOT THE 309 THE SOURCE FILE STATES.** The 309th was
--  هيئة الاستثمار, which is a MERGE SOURCE — a spelling of
--  الهيئة العامة للاستثمار والمناطق الحرة — and had been taken into the list
--  verbatim from a SPLIT's court part. The firm's review was consistent; the
--  first version of the generator was not. Counted, reported, and the counted
--  number used. The fifth time in this project that a stated count was wrong
--  while the list it described was right.
--
--  WHY NO NORMALISER COULD HAVE DONE THIS REVIEW — decision D22.
--  Ten spellings of the Investment Authority collapse into one court; they
--  differ by the definite article, by hamza, AND BY BRANCH LOCATION
--  (في صلاح سالم against بمدينة نصر). In the other direction the firm kept
--  القضاء الإداري, بالعباسية and بالإسكندرية apart: same name, different
--  buildings. A tool cannot tell those two cases apart, because the
--  difference is not in the text. **Both directions are asserted below** —
--  asserting only the fold would not notice an over-merge.
--
--  FOUR RULES CARRIED INTO STAGE 2 — full text in the source file:
--    1. A SPLIT row writes to MORE THAN ONE column. Never discard the
--       remainder.
--    2. Three raw values carry an INDIVIDUAL'S NAME, not a circuit — two
--       court experts and a prosecutor. They go to الجلسات.ملاحظات, the
--       HEARING note, not the matter note: the name belongs to the hearing it
--       was recorded against.
--    3. الجيزة الابتدائية / (السودان) — 5 rows where (السودان) is not a
--       circuit but is recorded as one. Loads as circuit text; flag at Gate 3.
--    4. A court value in neither the crosswalk nor lookup_court is a
--       QUARANTINE case. Never guess.
-- ==========================================================================

DO $COURT$
DECLARE
    n       integer;
    missing text;
BEGIN
    SELECT count(*) INTO n FROM "lookup_court";
    IF n <> 308 THEN
        RAISE EXCEPTION 'lookup_court: % rows, expected 308', n;
    END IF;

    SELECT count(*) INTO n FROM "migration_crosswalk" WHERE source_field = 'court';
    IF n <> 94 THEN
        RAISE EXCEPTION 'court crosswalk rules: %, expected 94', n;
    END IF;

    -- 52 MERGE + 35 SPLIT + 7 WRONG = 94. Each arm asserted, not just the sum.
    SELECT count(*) INTO n FROM "migration_crosswalk"
     WHERE source_field = 'court' AND target_field = 'court';
    IF n <> 52 THEN RAISE EXCEPTION 'MERGE rules: %, expected 52', n; END IF;

    SELECT count(*) INTO n FROM "migration_crosswalk"
     WHERE source_field = 'court' AND target_field = 'SPLIT';
    IF n <> 35 THEN RAISE EXCEPTION 'SPLIT rules: %, expected 35', n; END IF;

    SELECT count(*) INTO n FROM "migration_crosswalk"
     WHERE source_field = 'court'
       AND (target_field = 'matter_destination' OR target_field IS NULL);
    IF n <> 7 THEN RAISE EXCEPTION 'WRONG rules: %, expected 7', n; END IF;

    -- ----------------------------------------------------------------------
    --  NO CHAINS. THE ASSERTION THAT CAUGHT THE GENERATOR BUG.
    --
    --  A court that is also a crosswalk source means value -> court ->
    --  something else. Asserted regardless of how the label reached the list
    --  — a KEEP, a merge target, or a split's court part.
    -- ----------------------------------------------------------------------
    SELECT string_agg(c.label_ar, ', ') INTO missing
      FROM "lookup_court" c
      JOIN "migration_crosswalk" cw
        ON cw.source_value = c.label_ar AND cw.source_field = 'court';
    IF missing IS NOT NULL THEN
        RAISE EXCEPTION 'these are both a court and a crosswalk source, which is a two-step chain: %', missing;
    END IF;

    -- The dropped spelling must be gone from the list AND still resolve.
    SELECT count(*) INTO n FROM "lookup_court" WHERE label_ar = 'هيئة الاستثمار';
    IF n <> 0 THEN
        RAISE EXCEPTION 'هيئة الاستثمار is in the court list — it is a spelling of الهيئة العامة للاستثمار والمناطق الحرة, not a court';
    END IF;

    SELECT count(*) INTO n FROM "migration_crosswalk"
     WHERE source_field = 'court' AND source_value = 'هيئة الاستثمار'
       AND target_value = 'الهيئة العامة للاستثمار والمناطق الحرة';
    IF n <> 1 THEN
        RAISE EXCEPTION 'هيئة الاستثمار no longer resolves to the Investment Authority';
    END IF;

    -- ----------------------------------------------------------------------
    --  Every rule resolves
    -- ----------------------------------------------------------------------
    SELECT string_agg(cw.source_value, ', ') INTO missing
      FROM "migration_crosswalk" cw
     WHERE cw.source_field = 'court' AND cw.target_field = 'court'
       AND NOT EXISTS (SELECT 1 FROM "lookup_court" c WHERE c.label_ar = cw.target_value);
    IF missing IS NOT NULL THEN
        RAISE EXCEPTION 'merge targets that are not courts: %', missing;
    END IF;

    -- Every SPLIT's court part, AFTER resolution through the merge map.
    SELECT string_agg(cw.source_value, ', ') INTO missing
      FROM "migration_crosswalk" cw
     WHERE cw.source_field = 'court' AND cw.target_field = 'SPLIT'
       AND NOT EXISTS (SELECT 1 FROM "lookup_court" c WHERE c.label_ar = cw.target_value);
    IF missing IS NOT NULL THEN
        RAISE EXCEPTION 'SPLIT court parts that are not courts: %', missing;
    END IF;

    -- Every SPLIT must SAY where the remainder goes, or rule 1 has nothing to
    -- act on and the remainder is lost by omission.
    SELECT count(*) INTO n FROM "migration_crosswalk"
     WHERE source_field = 'court' AND target_field = 'SPLIT'
       AND (reviewer_note IS NULL
            OR (reviewer_note NOT LIKE '%circuit=%'
                AND reviewer_note NOT LIKE '%hearing_note=%'
                AND reviewer_note NOT LIKE '%case_number=%'));
    IF n <> 0 THEN
        RAISE EXCEPTION '% SPLIT rules do not say where the remainder goes', n;
    END IF;

    -- ----------------------------------------------------------------------
    --  D22, asserted in BOTH directions
    -- ----------------------------------------------------------------------
    SELECT count(*) INTO n FROM "migration_crosswalk"
     WHERE source_field = 'court'
       AND target_value = 'الهيئة العامة للاستثمار والمناطق الحرة';
    IF n < 9 THEN
        RAISE EXCEPTION 'only % spellings of the Investment Authority fold into one, expected at least 9', n;
    END IF;

    SELECT count(*) INTO n FROM "lookup_court"
     WHERE label_ar = 'الهيئة العامة للاستثمار والمناطق الحرة';
    IF n <> 1 THEN
        RAISE EXCEPTION 'the Investment Authority is not exactly one court';
    END IF;

    -- ...and the three administrative courts stay THREE. Same name, different
    -- buildings. A fuzzy match confident enough to fold the ten above would
    -- certainly have folded these.
    SELECT count(*) INTO n FROM "lookup_court"
     WHERE label_ar IN ('القضاء الإداري',
                        'القضاء الإداري بالعباسية',
                        'القضاء الإداري بالإسكندرية');
    IF n <> 3 THEN
        RAISE EXCEPTION 'the three administrative courts are % of 3 — different buildings, they must stay apart', n;
    END IF;

    -- ----------------------------------------------------------------------
    --  The three individuals, and the (السودان) row
    -- ----------------------------------------------------------------------
    SELECT count(*) INTO n FROM "migration_crosswalk"
     WHERE source_field = 'court' AND reviewer_note LIKE '%hearing_note=%';
    IF n <> 3 THEN
        RAISE EXCEPTION '% rules route a name to the HEARING note, expected 3', n;
    END IF;

    SELECT count(*) INTO n FROM "migration_crosswalk"
     WHERE source_field = 'court' AND target_value = 'الجيزة الابتدائية'
       AND reviewer_note LIKE '%(السودان)%';
    IF n <> 1 THEN
        RAISE EXCEPTION 'the الجيزة الابتدائية / (السودان) rule is missing';
    END IF;

    -- ----------------------------------------------------------------------
    --  The seven WRONG values, per the firm's ruling
    -- ----------------------------------------------------------------------
    SELECT count(*) INTO n FROM "lookup_matter_destination";
    IF n <> 31 THEN
        RAISE EXCEPTION 'lookup_matter_destination: %, expected 31 (27 + 4)', n;
    END IF;

    SELECT count(*) INTO n FROM "migration_crosswalk"
     WHERE source_field = 'court' AND target_field = 'matter_destination';
    IF n <> 5 THEN
        RAISE EXCEPTION 'destination rules: %, expected 5', n;
    END IF;

    SELECT string_agg(cw.source_value, ', ') INTO missing
      FROM "migration_crosswalk" cw
     WHERE cw.source_field = 'court' AND cw.target_field = 'matter_destination'
       AND NOT EXISTS (SELECT 1 FROM "lookup_matter_destination" d
                        WHERE d.label_ar = cw.target_value);
    IF missing IS NOT NULL THEN
        RAISE EXCEPTION 'destination targets that do not exist: %', missing;
    END IF;

    -- The two discards must be discards, and nothing else may be.
    SELECT count(*) INTO n FROM "migration_crosswalk"
     WHERE source_field = 'court' AND target_field IS NULL;
    IF n <> 2 THEN
        RAISE EXCEPTION 'court rules with no target: %, expected 2 (/ and 26)', n;
    END IF;

    SELECT count(*) INTO n FROM "migration_crosswalk"
     WHERE source_field = 'court' AND target_field IS NULL
       AND source_value IN ('/', '26');
    IF n <> 2 THEN
        RAISE EXCEPTION 'the two discards are not / and 26';
    END IF;

    -- Nothing is quarantined any more: the firm ruled on all seven.
    SELECT count(*) INTO n FROM "migration_crosswalk"
     WHERE source_field = 'court' AND target_field = 'quarantine';
    IF n <> 0 THEN
        RAISE EXCEPTION '% court rules are still quarantined', n;
    END IF;

    -- ----------------------------------------------------------------------
    --  Nothing else moved
    -- ----------------------------------------------------------------------
    SELECT count(*) INTO n FROM "migration_crosswalk";
    IF n <> 114 THEN
        RAISE EXCEPTION 'migration_crosswalk: % rows, expected 114 (20 + 94)', n;
    END IF;

    SELECT (SELECT count(*) FROM "lookup_matter_type")
         + (SELECT count(*) FROM "lookup_matter_category")
         + (SELECT count(*) FROM "lookup_degree")
         + (SELECT count(*) FROM "lookup_venue")
         + (SELECT count(*) FROM "lookup_importance")
         + (SELECT count(*) FROM "lookup_party_role")
         + (SELECT count(*) FROM "lookup_hearing_action")
         + (SELECT count(*) FROM "lookup_matter_destination")
         + (SELECT count(*) FROM "lookup_client_branch")
      INTO n;
    IF n <> 134 THEN
        RAISE EXCEPTION 'the nine original lists: % rows, expected 134 (130 + 4 destinations)', n;
    END IF;

    SELECT count(*) INTO n FROM "people";
    IF n <> 135 THEN RAISE EXCEPTION 'people: %, expected 135', n; END IF;

    RAISE NOTICE 'courts: 308 (309 stated, 1 was a merge source), 94 rules, 4 destinations added, 0 chains';
END
$COURT$;
